1	#!/usr/bin/env bun
2	/**
3	 * resolve_resume_agent.ts — Decide which agent `/resume` means.
4	 *
5	 * `/resume` is `/<agent>` with the name filled in from what actually ran here, so a
6	 * person who wants to continue does not have to remember whether it was the engineer
7	 * or the reviewer. That is the only thing it does differently, which is why it takes
8	 * no instruction: `/<agent>` already resumes the same session AND carries one.
9	 *
10	 * The name is read from the thread rather than stored anywhere, the same choice
11	 * `dispatch-chain.ts` makes about handoffs. Every result comment already carries
12	 * `AGENT_TAG` -- `post_result_comment.ts` writes it so a later run can recognise its
13	 * own past output -- so the most recent one is the answer, and there is nothing extra
14	 * to keep in sync.
15	 *
16	 * Writes `agent` to $GITHUB_OUTPUT, empty when there is nothing to resume.
17	 *
18	 * Usage:
19	 *   resolve_resume_agent.ts --number N
20	 */
21	import { appendFileSync } from "node:fs";
22	import { parseArgs } from "node:util";
23	import { gh } from "../../adapters/github/gh.ts";
24	import { LLM_CONTEXT_TAG } from "../../adapters/github/tags.ts";
25	import { mostRecentAgent, mostRecentAgentOn } from "../../adapters/github/agent-on-issue.ts";
26	import { commentBodies } from "../../adapters/github/thread.ts";
27	import { defineScript } from "./lib/script-ref.ts";
28	
29	export interface ResolveResumeAgentArgs {
30	  number: string | number;
31	}
32	
33	export const ref = defineScript<ResolveResumeAgentArgs>(import.meta.url);
34	
35	// `mostRecentAgent` and `mostRecentAgentOn` were defined here and are now in
36	// `adapters/github/agent-on-issue.ts`. The aggregation gate needed the same
37	// question answered -- "who was working on this node" -- and `app/` may not import
38	// from `entrypoints/`, so the reader moved to the layer both can reach. Re-exported
39	// because this module's own tests and `resume_subtree.ts` import them from here.
40	export { mostRecentAgent, mostRecentAgentOn };
41	
42	function main(): void {
43	  const { values } = parseArgs({ args: Bun.argv.slice(2), options: { number: { type: "string" } } });
44	  if (!values.number) {
45	    console.error("usage: resolve_resume_agent.ts --number N");
46	    process.exit(2);
47	  }
48	
49	  const repo = process.env.GITHUB_REPOSITORY ?? "";
50	  // The same read `/resume`'s sibling callers make, through `commentBodies` — the
51	  // pages past the first are split there, so a long thread names its agent instead of
52	  // throwing. This caller's policy differs from `mostRecentAgentOn`'s on purpose: it
53	  // logs the failure AND says so on the issue below, rather than answering "" silently.
54	  let agent = "";
55	  try {
56	    agent = mostRecentAgent(commentBodies(repo, values.number));
57	  } catch (error) {
58	    console.error(`Could not read comments on #${values.number}: ${error instanceof Error ? error.message : error}`);
59	  }
60	
61	  if (!agent) {
62	    // Said on the issue, not only in the log. `/resume` produces no run when it
63	    // resolves to nothing, and a command that silently does nothing is
64	    // indistinguishable from a broken workflow.
65	    gh(
66	      "issue", "comment", String(values.number), "--repo", repo,
67	      "--body",
68	      [
69	        LLM_CONTEXT_TAG.write("exclude"),
70	        "Atomaton: `/resume` found no previous run on this issue to continue. Use `/<agent>` to start one.",
71	      ].join("\n"),
72	    );
73	  }
74	
75	  const githubOutput = process.env.GITHUB_OUTPUT;
76	  if (githubOutput) appendFileSync(githubOutput, `agent=${agent}\n`);
77	  console.error(agent ? `Resuming ${agent}` : "Nothing to resume");
78	}
79	
80	if (import.meta.main) main();

